const project=(x,y,z)=>[cx+(m[0]*x+m[4]*y+m[8]*z)*scale,cy-(m[1]*x+m[5]*y+m[9]*z)*scale];
if(expansion>.02){c.strokeStyle='rgba(196,194,155,.13)';c.lineWidth=.6;c.setLineDash([2,5]);for(let a=0;a<TAU;a+=TAU/8){c.beginPath();for(let i=0;i<5;i++){const r=[4.95,3.94,3.29,2.72,2.02][i],z=(i-2)*layerSpread[i]*instrumentRings.spacing,[x,y]=project(Math.sin(a)*r,Math.cos(a)*r,z);i?c.lineTo(x,y):c.moveTo(x,y)}c.stroke()}c.setLineDash([])}
