async function startCamera(){if(cameraEnabled||cameraStarting){stopCamera();return}if(!navigator.mediaDevices?.getUserMedia){toast('当前环境无法访问摄像头，请用 HTTPS 浏览器打开');return}cameraStarting=true;$('camera').disabled=true;$('camera').innerHTML='<span>◌</span> 正在准备';try{const v=await import('./vendor/vision_bundle.mjs');if(!cameraStarting)return;if(!detector){const files=await v.FilesetResolver.forVisionTasks('./vendor/wasm');detector=await v.HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'./vendor/hand_landmarker.task',delegate:'CPU'},runningMode:'VIDEO',numHands:1,minHandDetectionConfidence:.6,minHandPresenceConfidence:.6,minTrackingConfidence:.6})}if(!cameraStarting)return;stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});if(!cameraStarting){stream.getTracks().forEach(t=>t.stop());return}video.srcObject=stream;await video.play();cameraEnabled=true;cameraStarting=false;lastVideoTime=-1;lastHandSeen=performance.now();$('camera-box').hidden=false;$('camera').disabled=false;$('camera').classList.add('active');$('camera').innerHTML='<span>◉</span> 关闭手势';$('camera-status').textContent='请将整只手放入画面';visionLoop(performance.now())}catch(e){console.error(e);stopCamera();toast(e.name==='NotAllowedError'?'未获得摄像头权限，仍可用鼠标或触屏操作':e.name==='NotFoundError'?'未找到摄像头，仍可用鼠标或触屏操作':'手势组件暂时无法启动，请重试或使用鼠标操作')}}
